/* global self, caches, fetch, Response, URL */

/**
 * Work 360 AI — service worker.
 *
 * Hand-written rather than generated by a build plugin, for two reasons:
 *
 *  1. `index.html` carries a stale-bundle self-heal script that refetches `/`
 *     with `cache: 'no-store'` and compares the served asset hashes to the
 *     ones the current document is loading. A precaching worker that answers
 *     that probe from CacheStorage would make the two sides disagree forever
 *     and reload-loop the tab. This worker recognises the probe (it carries
 *     `X-Bundle-Check: 1`) and always sends it straight to the network.
 *  2. The API, the socket and the uploads must never be cached — a stale lead
 *     list or a cached 401 is far worse than a slow one.
 *
 * Strategy summary:
 *   /api, /socket.io, /uploads, /health, non-GET, cross-origin  → network only
 *   /assets/<hash>.js|css                                       → cache first
 *   navigations (SPA routes)                                    → network first
 *   icons, manifest, favicon, other same-origin files           → stale-while-revalidate
 *
 * Bump SW_VERSION when any of the logic below changes: the name change is what
 * makes `activate` drop the previous generation of caches.
 */

const SW_VERSION = 'v1';
const SHELL_CACHE = `w360-shell-${SW_VERSION}`;
const ASSET_CACHE = `w360-assets-${SW_VERSION}`;
const STATIC_CACHE = `w360-static-${SW_VERSION}`;
const EXPECTED_CACHES = [SHELL_CACHE, ASSET_CACHE, STATIC_CACHE];

/** Canonical key for the app shell HTML, whatever SPA route requested it. */
const SHELL_KEY = '/index.html';
const OFFLINE_URL = '/offline.html';

/**
 * Files worth having before the first offline load. Deliberately tiny: the
 * hashed bundles are NOT precached because their names change every deploy and
 * this worker has no build step to learn them — they land in ASSET_CACHE on
 * first use instead, which is enough to make the second visit work offline.
 */
const PRECACHE_URLS = [OFFLINE_URL, '/manifest.webmanifest', '/icon-192.png'];

/**
 * Paths that must always hit the network. Everything authenticated lives under
 * /api — a cached lead list, or worse a cached 401, is far more damaging than a
 * slow one.
 */
const NETWORK_ONLY_PREFIXES = ['/api/', '/socket.io/', '/uploads/', '/health'];

/** Cap on cached hashed assets, so deploy after deploy can't grow unbounded. */
const ASSET_CACHE_MAX_ENTRIES = 160;

/** Same-origin static files worth serving instantly from cache. */
const STATIC_FILE_RE = /\.(?:png|svg|ico|webmanifest|woff2?|ttf|webp|jpe?g)$/i;

self.addEventListener('install', (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(STATIC_CACHE);
      // addAll() rejects the whole install if any single file 404s, which would
      // leave the app with no worker at all. Precaching is an optimisation —
      // do it per-file and tolerate misses.
      await Promise.all(
        PRECACHE_URLS.map(async (url) => {
          try {
            const res = await fetch(url, { cache: 'no-cache' });
            if (res && res.ok) await cache.put(url, res.clone());
          } catch {
            /* Offline during install — the runtime handlers will fill in. */
          }
        }),
      );
    })(),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const names = await caches.keys();
      await Promise.all(
        names
          .filter((n) => n.startsWith('w360-') && !EXPECTED_CACHES.includes(n))
          .map((n) => caches.delete(n)),
      );
      await self.clients.claim();
    })(),
  );
});

/**
 * The page asks for the update to be applied (see registerServiceWorker.ts).
 * We never call skipWaiting() on our own: swapping the worker under a tab that
 * is mid-form or mid-voice-session is a worse experience than a "Reload" chip.
 */
self.addEventListener('message', (event) => {
  if (event.data && event.data.type === 'SKIP_WAITING') {
    self.skipWaiting();
  }
});

function isNetworkOnly(url) {
  return NETWORK_ONLY_PREFIXES.some((p) => url.pathname.startsWith(p));
}

function isHashedAsset(url) {
  return url.pathname.startsWith('/assets/');
}

async function trimCache(cacheName, maxEntries) {
  const cache = await caches.open(cacheName);
  const keys = await cache.keys();
  // Cache.keys() preserves insertion order, so the front of the list is the
  // oldest thing we stored — close enough to LRU for immutable assets.
  const excess = keys.length - maxEntries;
  for (let i = 0; i < excess; i++) {
    await cache.delete(keys[i]);
  }
}

/** Hashed bundle: immutable by construction, so cache first and never revalidate. */
async function cacheFirst(request) {
  const cache = await caches.open(ASSET_CACHE);
  const hit = await cache.match(request);
  if (hit) return hit;
  const res = await fetch(request);
  if (res && res.ok && res.type === 'basic') {
    await cache.put(request, res.clone());
    void trimCache(ASSET_CACHE, ASSET_CACHE_MAX_ENTRIES);
  }
  return res;
}

/**
 * SPA navigation: always try the network so a deploy is picked up on the very
 * next load, and fall back to the last good shell (then the offline page) when
 * the device has no connection.
 */
async function navigateNetworkFirst(request) {
  const cache = await caches.open(SHELL_CACHE);
  try {
    const res = await fetch(request);
    if (res && res.ok) {
      // Store under one canonical key: every SPA route returns the same shell,
      // so keying by URL would cache the identical HTML dozens of times.
      await cache.put(SHELL_KEY, res.clone());
    }
    return res;
  } catch {
    const shell = await cache.match(SHELL_KEY);
    if (shell) return shell;
    const offline = await caches.match(OFFLINE_URL);
    if (offline) return offline;
    return new Response(
      '<!doctype html><title>Offline</title><h1>Offline</h1>',
      { status: 503, headers: { 'Content-Type': 'text/html; charset=utf-8' } },
    );
  }
}

/** Icons, manifest, favicon: serve instantly, refresh quietly in the background. */
async function staleWhileRevalidate(request) {
  const cache = await caches.open(STATIC_CACHE);
  const hit = await cache.match(request);
  const network = fetch(request)
    .then((res) => {
      if (res && res.ok && res.type === 'basic') {
        void cache.put(request, res.clone());
      }
      return res;
    })
    .catch(() => null);
  if (hit) {
    void network;
    return hit;
  }
  const res = await network;
  if (res) return res;
  throw new Error('offline and not cached');
}

self.addEventListener('fetch', (event) => {
  const { request } = event;

  // Never touch anything that isn't a plain same-origin GET: POSTs mutate,
  // cross-origin responses are opaque, and Range requests (audio/video
  // seeking) break when replayed from a cache.
  if (request.method !== 'GET') return;
  if (request.headers.has('range')) return;

  let url;
  try {
    url = new URL(request.url);
  } catch {
    return;
  }
  if (url.origin !== self.location.origin) return;
  if (isNetworkOnly(url)) return;

  // The stale-bundle self-heal probe must see what the SERVER thinks the
  // current bundle is. Answering it from a cache would either mask a real
  // deploy or invent a phantom mismatch that reload-loops the tab.
  if (request.headers.get('X-Bundle-Check') === '1') return;

  if (request.mode === 'navigate') {
    event.respondWith(navigateNetworkFirst(request));
    return;
  }

  if (isHashedAsset(url)) {
    event.respondWith(cacheFirst(request));
    return;
  }

  // Everything else same-origin and static: the icons, the manifest, the .ico.
  if (STATIC_FILE_RE.test(url.pathname)) {
    event.respondWith(
      staleWhileRevalidate(request).catch(() => fetch(request)),
    );
  }
});
